uv run python -c 'import sys,tempfile; from pathlib import Path; sys.path[:0]=["tests"]; import test_trust_mutants as T; r=Path(tempfile.mkdtemp())/"p"; T.scaffold(r,""); (r/"lean/Demo/Defs.lean").write_text("namespace Demo\n\nclass Small (n : Nat) where\n  val : Nat\n\ninstance : Small 0 := ⟨0⟩\n\ninstance [s : Small n] : Small (n + 1) := ⟨s.val + 1⟩\n\nstructure W (n : Nat) where\n  k : Nat\n\ninstance (priority := low) wFallback : BEq (W n) := ⟨fun _ _ => false⟩\n\ninstance wSmall [Small n] : BEq (W n) := ⟨fun _ _ => true⟩\n\nstructure Limits where\n  depth : Nat := 126\n\ndef Limits.str : Nat → Bool\n  | 0 => (⟨0⟩ : W ({} : Limits).depth) == ⟨0⟩\n  | k + 1 => Limits.str k\n\n#guard Limits.str 3\n\nend Demo\n"); T.dump(r,Path(tempfile.mkdtemp()),[]); T.git(r,"add","."); T.git(r,"commit","-qm","head"); s=[(m["operator"],m["status"],m["detail"][:90]) for m in T.of(T.tool(r,r.parent/"run")[1],"Limits")]; print(s); assert s and not any(x=="KILLED" for _,x,_ in s), s'
